-- Secuencia Oportunidad · Moda multitienda — 7 plantillas

insert into email_templates (nombre, asunto, preview_text, tipo, layout, categoria, bloques, activo)
values ('Oportunidad 1 · Diagnóstico', 'Lo que vi de tu operación en la demo', 'No lo que te enseñé. Lo que tu equipo hace hoy para saber qué talla queda.', 'automatizado', 'simple', 'ventas',
        '[{"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, casi todos los correos después de una demo repiten lo que el sistema hace.\n\nEste va al revés: lo que vi de TU operación mientras te enseñaba pantallas."}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "Tres cosas que anoté"}, {"id": "l1", "tipo": "lista", "items": ["Para saber qué tallas quedan en tus tiendas, alguien tiene que preguntar. Ese «alguien» tiene nombre en tu equipo, y ese trabajo no aparece en ningún costo — pero se paga todos los días.", "Cuando una talla se agota a media temporada, tu sistema deja de venderla y **se queda callado**. No distingue entre «no gustó» y «se acabó». Vas a comprar la próxima corrida con ese hueco adentro.", "El catálogo carga años de decisiones de otra gente: la misma prenda dada de alta más de una vez, tallas escritas de tres formas distintas, costos que nadie ha revisado."]}, {"id": "i1", "tipo": "imagen", "src": "https://www.sacscloud.com/email/moda/moda-matriz.png", "alt": "Matriz de tallas y colores con siete celdas en cero", "pie": "Un solo modelo: seis tallas en cuatro colores. Siete están en cero."}, {"id": "t2", "tipo": "texto", "texto": "Y hay una cuarta que no anoté, porque no estaba en la pantalla. Estaba en cómo hablaste del inventario.\n\n**No es que te falte inventario. Te sobra inventario descabalado.** Se pueden tener ocho mil piezas y que solo mil novecientas sean vendibles, porque de cada estilo ya solo quedan la XS y la XXL.\n\nEl reporte dice que estás sano. El rack dice otra cosa."}, {"id": "t3", "tipo": "texto", "texto": "Nada de eso es un problema de esfuerzo. Tu equipo ya está haciendo de más para taparlo."}, {"id": "s1", "tipo": "separador"}, {"id": "h2", "tipo": "encabezado", "nivel": 2, "texto": "Sobre la cotización"}, {"id": "t4", "tipo": "texto", "texto": "Cuando circule internamente, alguien va a leer el total y no el plan. Por eso te la mando partida en dos:"}, {"id": "d1", "tipo": "dos_columnas", "izquierda": {"titulo": "Fase 1 — que el piso deje de sangrar", "texto": "Catálogo con tallas y colores, inventario vivo en todas tus tiendas, caja y cortes. Esto cambia la semana uno."}, "derecha": {"titulo": "Fase 2 — que la compra deje de ser a ojo", "texto": "Demanda por talla, corridas por color y nivelación entre tiendas. Esto cambia la temporada siguiente."}}, {"id": "t5", "tipo": "texto", "texto": "No hay que arrancar todo el mismo día. Hay que arrancar en el orden correcto."}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Si tu conclusión de la demo fue «esto nos queda grande hoy», dímelo con esas palabras. La fase 1 sola es una conversación distinta y más barata, y prefiero tenerla a que el proyecto se muera en silencio."}]'::jsonb, true);

insert into email_templates (nombre, asunto, preview_text, tipo, layout, categoria, bloques, activo)
values ('Oportunidad 2 · Las 7 preguntas', 'Las 7 preguntas antes de firmar cualquier sistema', 'Escritas para que se las hagas a todos. A nosotros incluidos.', 'automatizado', 'simple', 'ventas',
        '[{"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, hoy no te vengo a vender nada.\n\nTe mando el criterio con el que yo evaluaría un sistema si vendiera ropa en más de una tienda. Es agnóstico: sirve para todos los que estés viendo, nosotros incluidos."}, {"id": "i1", "tipo": "imagen", "src": "https://www.sacscloud.com/email/moda/moda-hoja-linea.jpg", "alt": "Hoja de línea impresa con la corrida de tallas, un lápiz y una tarjeta de swatches", "pie": "La hoja de línea: donde de verdad se decide la temporada."}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "Las siete"}, {"id": "l1", "tipo": "lista", "items": ["**¿Cuándo una talla se agota, el sistema lo sabe o solo ve que dejó de venderse?** Es la diferencia entre «la M no gustó» y «la M se acabó el día 9». Si no lo distingue, tu próxima compra repite el error.", "**Si me sugiere una corrida por color, ¿puedo ver con qué criterio la calculó?** Pide la fórmula. Si la respuesta es «es un algoritmo», es una caja negra y tú firmas la orden de compra.", "**¿Cómo ordena mis tallas?** Que te enseñen un reporte con 22.5 y otro con XS a XXL. Si revuelve las numéricas con las alfabéticas, vas a pelear con ese reporte cada semana durante años.", "**En el pico, ¿cuántas ventas por minuto ha aguantado con un cliente real?** Pide el número y el nombre del evento. No aceptes adjetivos.", "**¿Quién limpia mi catálogo, cuánto tarda y quién lo paga?** Pide el plan en semanas. Aquí es donde se mueren la mayoría de las implementaciones.", "**Cuando la prenda está en la tienda equivocada, ¿me avisa el sistema o tengo que ir a buscarla?** Un reporte que hay que abrir no es una alerta.", "**El sábado de Buen Fin a las 6 de la tarde, ¿quién contesta y en cuánto?** Pide un nombre. No un correo de soporte."]}, {"id": "a1", "tipo": "aviso", "texto": "Haznos estas siete a nosotros también. Si alguna respuesta nuestra no te convence, quiero enterarme ANTES de que firmes, no después."}, {"id": "t2", "tipo": "texto", "texto": "Y si sales de este ejercicio decidiendo por otro camino, habrá valido la pena. Elegir mal aquí cuesta dos años."}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Si ya te la sabes y solo te falta el sí de alguien más, la lista sirve igual: es una hoja que se reenvía sin que tengas que explicar el proyecto."}]'::jsonb, true);

insert into email_templates (nombre, asunto, preview_text, tipo, layout, categoria, bloques, activo)
values ('Oportunidad 3 · El hueco de curva', 'La talla que vendió cero porque nunca estuvo', 'Tu sistema la anotó como talla muerta. Y con eso compraste la siguiente.', 'automatizado', 'simple', 'ventas',
        '[{"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, te debo una demostración de algo que en la demo pasó rápido.\n\nLa M se agotó el día 9. Los otros cincuenta y un días del periodo vendió cero — porque no había qué vender."}, {"id": "i1", "tipo": "imagen", "src": "https://www.sacscloud.com/email/moda/moda-hueco-curva.png", "alt": "Dos gráficas: la talla M con tres ventas al inicio y sin existencia el resto del periodo, y la XXL con tres ventas repartidas", "pie": "Las dos vendieron tres piezas. Solo una tiene demanda."}, {"id": "t2", "tipo": "texto", "texto": "Cuando llega el momento de comprar, el reporte dice que la M vendió 3 piezas. Y que la XXL vendió 3 piezas.\n\n**Parecen el mismo dato. Son lo contrario.** Una se acabó al inicio. La otra estuvo colgada dos meses y nadie la quiso.\n\nCompras la siguiente corrida con ese hueco adentro. Y la temporada que viene vuelves a quedarte sin M."}, {"id": "s1", "tipo": "separador"}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "Lo que hace el nuestro"}, {"id": "t3", "tipo": "texto", "texto": "Detecta que la talla estuvo agotada y estima lo que **habría** vendido. Y no te impone el método: eliges uno de cinco."}, {"id": "l1", "tipo": "lista", "items": ["**Promedio de tallas hermanas.** Rellena el hueco con el promedio de lo que se sugiere para las tallas que sí venden. Equilibrado.", "**Mínimo fijo por talla.** Trae al menos una cantidad fija de cada talla faltante. Tú defines cuántas.", "**Histórico de esa talla.** La estima con SU propia venta en un periodo más largo — para cuando estuvo agotada en el periodo que elegiste, pero antes sí vendía.", "**Plantilla de curva por categoría.** Usa la curva objetivo que tú definiste: S:1, M:3, L:3, XL:2.", "**No estimar.** Solo marca el hueco y tú decides a mano. Conservador."]}, {"id": "a1", "tipo": "aviso", "texto": "Y un detalle que dice más que los cinco métodos juntos: si la categoría no tiene curva definida, el cuarto **cae solo al promedio** en vez de tronar. Eso no se le ocurre a quien no ha vivido una temporada de compras."}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Tráeme un estilo tuyo de la temporada pasada —el que se te haya descabalado más rápido— y te enseño cuánto cambia la sugerencia de compra según cuál de los cinco elijas. Es la prueba más rápida que existe de si esto te sirve."}]'::jsonb, true);

insert into email_templates (nombre, asunto, preview_text, tipo, layout, categoria, bloques, activo)
values ('Oportunidad 4 · No hay que comprar, hay que mover', 'No hay que comprar. Hay que mover.', 'Polanco no tiene M ni L. En la cadena hay cinco y siete.', 'automatizado', 'simple', 'ventas',
        '[{"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, ayer te conté cómo se compra mal. Hoy, algo peor: comprar lo que ya tienes."}, {"id": "i1", "tipo": "imagen", "src": "https://www.sacscloud.com/email/moda/moda-multitienda.png", "alt": "Matriz de una prenda en cuatro tiendas: Polanco en cero en M y L, con existencia en las otras", "pie": "Una prenda, cuatro tiendas. La decisión está en el renglón de abajo."}, {"id": "t2", "tipo": "texto", "texto": "En Polanco faltan la M y la L. Son las dos que más vende esa tienda, así que la vendedora las pide en la siguiente orden de compra — y hace bien, desde donde ella ve.\n\nPero en la cadena hay **cinco M y siete L**. Están en Satélite y en Perisur, colgadas, envejeciendo, camino a la rebaja de fin de temporada.\n\nComprar más sería pagar dos veces por el mismo error."}, {"id": "s1", "tipo": "separador"}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "Lo que cambia con varias tiendas"}, {"id": "l1", "tipo": "lista", "items": ["**La clienta que pide la M.** No hay aquí, hay tres en la otra tienda, y se aparta desde el mostrador antes de que se vaya. Hoy esa venta se pierde y **no aparece en ningún reporte**, porque una venta que no ocurrió no se registra.", "**El traspaso se sugiere solo.** El sistema ve el hueco de una tienda y el excedente de otra, y propone el movimiento — con su documento, no en la camioneta del gerente.", "**La compra se hace sobre la cadena, no sobre la tienda.** Primero se acomoda lo que ya pagaste. Lo que falte después, eso sí se compra."]}, {"id": "t3", "tipo": "texto", "texto": "Esto es lo que un sistema de una sola tienda no puede hacer aunque quiera: no tiene con qué comparar."}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Un dato del que casi nadie se entera a tiempo: cada traspaso de más de 30 kilómetros necesita CFDI de traslado con complemento Carta Porte 3.1, y la multa va de $17,020 a $51,060 pesos. Si hoy mueves mercancía sin papel, no es un regaño — es que el sistema debería generarte ese documento solo."}]'::jsonb, true);

insert into email_templates (nombre, asunto, preview_text, tipo, layout, categoria, bloques, activo)
values ('Oportunidad 5 · El caso y la parte fea', '150 mil ventas sin un error (y la parte fea)', 'El caso que sí se parece a tu temporada alta, incluido lo que costó.', 'automatizado', 'simple', 'ventas',
        '[{"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, un caso del que casi nunca cuento la segunda mitad."}, {"id": "c1", "tipo": "cita", "texto": "En un concierto perdimos 20% de ventas en dos horas porque el sistema colapsó. Con SACS eso no vuelve a pasar.", "autor": "Mariana López · Directora de Operaciones, LiveShow"}, {"id": "t2", "tipo": "texto", "texto": "LiveShow vende merch de giras en México: playeras y hoodies con tallas, en cientos de puntos de venta simultáneos. Shakira, Metallica, Karol G, Lady Gaga."}, {"id": "m1", "tipo": "metricas", "items": [{"cifra": "150,000+", "texto": "transacciones sin un error"}, {"cifra": "4 / min", "texto": "ventas en hora pico"}, {"cifra": "+15%", "texto": "ticket promedio"}]}, {"id": "t3", "tipo": "texto", "texto": "Tú no vendes en estadios. Pero tu sábado de Buen Fin es eso a menor escala: cola larga, gente que se va si tarda, y CERO posibilidad de resurtir. En un evento, el inventario que llegó es todo el que habrá. En tu temporada, la corrida que compraste es toda la que habrá."}, {"id": "t4", "tipo": "texto", "texto": "Por eso el dato que a mí me obsesiona no es el pico. Es este: en México **se devuelve el 35% de lo que se vende de moda en línea** —la tasa más alta de todas las categorías del país— y **un tercio de esas devoluciones es por talla equivocada**.\n\nEso no es un problema de paquetería. Es no saber qué talla tienes, y dónde."}, {"id": "s1", "tipo": "separador"}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "Ahora la parte fea"}, {"id": "i1", "tipo": "imagen", "src": "https://www.sacscloud.com/email/moda/moda-botas.jpg", "alt": "Par de botas western de piel labrada sobre fondo hueso", "pie": "Botas: medias tallas más ancho. La corrida más difícil que hay en moda."}, {"id": "l1", "tipo": "lista", "items": ["**El catálogo duele.** Alazanas y Forja Western venden botas en tienda física — medias tallas, 22.5, 23.5, 24.5, más el ancho. Pero antes de que el sistema sugiera una sola compra hay un trabajo que nadie presume: limpiar prendas duplicadas, tallas escritas de tres formas y costos que nadie revisó en años. Si tu catálogo está sucio, esas semanas van a existir. Conmigo o con quien elijas.", "**El equipo se resiste.** Siempre hay alguien en piso que lleva años con su método y que la primera semana va a decir que antes era más rápido. Tiene razón la primera semana. Deja de tenerla en la tercera.", "**No se migra todo.** Se migra el catálogo activo, existencias por tienda, clientes y apartados abiertos. NO se migran años de histórico del sistema viejo ni prendas muertas: arrastrar basura es la forma más común de estrenar un sistema que ya nace sucio."]}, {"id": "t5", "tipo": "texto", "texto": "Te lo digo ahora porque si esto te lo cuento después de firmar, se llama sorpresa. Antes de firmar, se llama plan."}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Y el punto que nadie pregunta hasta que es tarde: el sábado de temporada a las 6 de la tarde no le escribes a un buzón de soporte. Me escribes a mí — la misma persona que te implementó. Confírmame en la propuesta la ventana de guardia que necesitas y la dejamos por escrito."}]'::jsonb, true);

insert into email_templates (nombre, asunto, preview_text, tipo, layout, categoria, bloques, activo)
values ('Oportunidad 6 · El probador virtual', 'Y una que todavía no te enseñé', 'En tu tienda caben 200 prendas. En tu catálogo hay 2,000.', 'automatizado', 'simple', 'ventas',
        '[{"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, los dos correos anteriores fueron de lo que no se ve: cómo se compra y cómo se mueve.\n\nEste es de lo que sí se ve."}, {"id": "i1", "tipo": "imagen", "src": "https://www.sacscloud.com/email/moda/moda-probador.jpg", "alt": "Pantalla interactiva de pie en una boutique, mostrando la retícula del catálogo de prendas", "pie": "El probador virtual se alimenta de tu catálogo. No hay que cargar nada aparte."}, {"id": "t2", "tipo": "texto", "texto": "Una pantalla en el piso donde tu clienta prueba prendas y arma combinaciones —colores y tallas— sin buscar en el rack ni hacer fila para el probador.\n\nY lo importante no es la pantalla. Es lo que muestra."}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "En tu tienda caben doscientas prendas. En tu catálogo hay dos mil."}, {"id": "t3", "tipo": "texto", "texto": "Esa es toda la idea. El rack solo puede enseñar lo que cupo en el piso de esa tienda. La pantalla enseña **tu catálogo completo** — incluido lo que está en la otra sucursal.\n\nEs el mismo argumento del correo de antier, pero visto desde el lado de la clienta: la prenda que le iba a encantar existe, solo que no está colgada frente a ella."}, {"id": "l1", "tipo": "lista", "items": ["**Se alimenta de tu catálogo.** El mismo que ya vive en el sistema. Nadie sube fotos aparte ni mantiene dos inventarios.", "**Sigue la existencia real.** Si una talla se acabó, deja de aparecer. La clienta nunca se ilusiona con algo que no puedes darle.", "**Ella se prueba más de lo que se probaría.** Sin fila, sin cargar seis prendas al probador, sin pedirle a nadie que vaya a buscar la otra talla."]}, {"id": "t4", "tipo": "texto", "texto": "Te lo enseño cuando quieras. Solo que después de la operación, no antes: primero que el piso y la compra estén firmes, y esto encima."}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Si tu catálogo hoy no tiene fotos consistentes, esto no se ve bien y no vale la pena. Es otra razón para que la semana 1 del catálogo se haga bien: la misma limpieza que hace que la compra funcione es la que hace que la vitrina se vea."}]'::jsonb, true);

insert into email_templates (nombre, asunto, preview_text, tipo, layout, categoria, bloques, activo)
values ('Oportunidad 7 · La decisión', 'Dos fechas y una resta', 'Tres respuestas son válidas. Una de ellas me saca de tu bandeja.', 'automatizado', 'simple', 'ventas',
        '[{"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, dos fechas y una resta. Y te dejo en paz."}, {"id": "t2", "tipo": "texto", "texto": "La primera ya está corriendo: desde enero, la ropa que entra sin tratado paga **35% de arancel**. No el 50% que titularon los medios —ese es el techo de otras fracciones—, y con IVA el multiplicador sobre valor en aduana queda en 1.57.\n\nLas tres rutas baratas se cerraron: IMMEX para prenda terminada, depósito fiscal y recinto fiscalizado. Por primera vez en años, **comprar bien pesa más que comprar barato**."}, {"id": "t3", "tipo": "texto", "texto": "La segunda es Intermoda de enero. Cuatro días en Expo Guadalajara para comprometer seis meses de capital. La única pregunta que importa es si vas a llegar ahí con el sell-through por estilo y por tienda de esta temporada, o con lo que te acuerdes."}, {"id": "s1", "tipo": "separador"}, {"id": "t4", "tipo": "texto", "texto": "Y ahora la resta. El Buen Fin cae a mediados de noviembre. La implementación son 4 semanas y el rodaje son 2 más. Súmale una semana entre firma y arranque real, porque siempre existe.\n\nPara llegar a tu temporada fuerte con el sistema ya rodado —no estrenándolo— la decisión tiene que estar tomada alrededor del 1 de octubre.\n\n**No es una fecha de venta. Es una resta.**"}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "Tres respuestas, las tres válidas"}, {"id": "l1", "tipo": "lista", "items": ["**Arrancamos.** Me lo confirmas esta semana, bloqueo el calendario de implementación y la semana 1 empieza de inmediato. Entras al Buen Fin con la operación ya corriendo.", "**Lo movemos.** Perfecto, y con lógica: no se arranca dentro de temporada. Cierro esta conversación, te escribo una sola vez cuando toque y retomamos donde quedamos, sin volver a empezar.", "**No es para ustedes.** También está bien. Dímelo y dejo de escribirte hoy mismo."]}, {"id": "a1", "tipo": "aviso", "texto": "Un no claro me sirve más que un tal vez. El tal vez nos cuesta tiempo a los dos: a mí me deja un proyecto abierto que no lo está, y a ti una decisión pendiente que se vuelve a discutir cada junta."}, {"id": "t5", "tipo": "texto", "texto": "Contéstame con el número. Con eso me basta."}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Si tu respuesta es la 3 porque el precio no cierra, dímelo así de directo. No hay descuento de última hora ni lo va a haber — pero sí hay una fase 1 más chica que resuelve el piso de venta y deja la compra para después. Si eso no aplica, cerramos en buenos términos y aquí quedo para cuando cambie el momento."}]'::jsonb, true);

-- ── La secuencia y sus 7 pasos ──────────────────────────────────────────────
-- Nace APAGADA (activa=false). Prenderla manda correos a prospectos reales con
-- cotización en la mano: es una decisión de negocio, no un detalle de carga.
with s as (
  insert into crm_secuencias (nombre, descripcion, activa, entrada, corte_dias, objetivo, dias_envio, hora_inicio, hora_fin)
  values (
    'Oportunidad · Moda multitienda',
    'Diez días de pura credibilidad para marcas de moda que ya vieron la demo y ya tienen cotización. Diagnóstico, criterio de compra agnóstico, dos piezas de producto que nadie más nombra, el caso de LiveShow con su parte fea, el probador virtual y el cierre por calendario. Solo correo.',
    false,
    '{"estatus": ["cotizado", "agendado", "respondio"], "lifecycle": ["oportunidad"]}'::jsonb,
    12, 'convertido', '[1,2,3,4,5]'::jsonb, 10, 18)
  returning id
)
insert into crm_secuencia_pasos (secuencia_id, orden, dia, canal, email_template_id, activo)
select s.id, p.orden, p.dia, 'correo', t.id, true
from s
cross join (values
  (1,  1,  'Oportunidad 1 · Diagnóstico'),
  (2,  3,  'Oportunidad 2 · Las 7 preguntas'),
  (3,  5,  'Oportunidad 3 · El hueco de curva'),
  (4,  6,  'Oportunidad 4 · No hay que comprar, hay que mover'),
  (5,  8,  'Oportunidad 5 · El caso y la parte fea'),
  (6,  9,  'Oportunidad 6 · El probador virtual'),
  (7,  10, 'Oportunidad 7 · La decisión')
) as p(orden, dia, plantilla)
join email_templates t on t.nombre = p.plantilla;
